      if (el_btn_25) el_btn_25.addEventListener('click', () => filter.value = 'all');
      const el_btn_26 = this.shadowRoot.getElementById('btn_26');
      if (el_btn_26) el_btn_26.addEventListener('click', () => filter.value = 'active');
